inline juce::String presetName(juce::String source,double bpm){auto tempo=juce::String(bpm,2);while(tempo.containsChar('.')&&tempo.endsWithChar('0'))tempo=tempo.dropLastCharacters(1);if(tempo.endsWithChar('.'))tempo=tempo.dropLastCharacters(1);auto name=juce::File::createLegalFileName(juce::File(source).getFileNameWithoutExtension());if(name.isEmpty())name="Slices";return tempo+"bpm "+name;}
struct Region {std::shared_ptr<const AudioData> audio;std::vector<Slice> slices;juce::String error;};
inline Region crop(std::shared_ptr<const AudioData> source,const std::vector<Slice>& slices,int begin,int end,int repeatFrames=0){
 Region result;if(!source||begin<0||end<=begin){result.error="Invalid TAL loop region.";return result;}int frames=end-begin,channels=source->buffer.getNumChannels(),available=source->buffer.getNumSamples();
 if(channels<1||(int64_t)frames*channels*4>1024LL*1024*1024){result.error="TAL export region exceeds the 1 GB audio limit.";return result;}
 auto data=std::make_shared<AudioData>();data->rate=source->rate;data->path=source->path;data->librarySourcePath517=source->librarySourcePath517;data->buffer.setSize(channels,frames);data->buffer.clear();
 for(int offset=0;offset<frames;){int position=begin+offset,point=repeatFrames>0?position%repeatFrames:position;int count=juce::jmin(frames-offset,repeatFrames>0?repeatFrames-point:frames-offset);int valid=juce::jlimit(0,count,available-point);if(point>=0&&point<available)for(int ch=0;ch<channels;++ch)data->buffer.copyFrom(ch,offset,source->buffer,ch,point,valid);offset+=count;}
 int first=repeatFrames>0?begin/repeatFrames:0,last=repeatFrames>0?(end-1)/repeatFrames:0;
 for(int pass=first;pass<=last;++pass){int64_t shift=repeatFrames>0?(int64_t)pass*repeatFrames:0;for(const auto& slice:slices){int64_t start=juce::jmax((int64_t)begin,(int64_t)slice.start+shift),stop=juce::jmin((int64_t)end,(int64_t)juce::jmin(available,slice.audibleEnd(source->rate))+shift);if(stop<=start)continue;Slice copy=slice;copy.start=(int)(start-begin);copy.end=(int)(stop-begin);copy.playbackEnd=1;copy.playbackLengthMs=-1;result.slices.push_back(copy);if(result.slices.size()>92){result.error="TAL export supports up to 92 slices, starting at MIDI 36.";return result;}}}
 if(result.slices.empty()){result.error="No slices intersect the current loop region.";return result;}result.audio=data;return result;
}
inline juce::Result write(juce::File destination,std::shared_ptr<const AudioData> audio,const std::vector<Slice>& slices,bool unique=false,juce::File* saved=nullptr,int regionStart=0,int regionEnd=-1,int repeatFrames=0){
 if(!audio||audio->buffer.getNumSamples()<1||slices.empty())return juce::Result::fail("No slices to export.");
 if(regionEnd>=0){auto region=crop(audio,slices,regionStart,regionEnd,repeatFrames);if(region.error.isNotEmpty())return juce::Result::fail(region.error);return write(destination,region.audio,region.slices,unique,saved);}
 if(slices.size()>92)return juce::Result::fail("TAL export supports up to 92 slices, starting at MIDI 36.");
 static juce::CriticalSection mutex;const juce::ScopedLock guard(mutex);
 if(destination.getParentDirectory().createDirectory().failed())return juce::Result::fail("Could not create the TAL export folder.");
 if(unique)destination=destination.getNonexistentSibling();
 auto parent=destination.getParentDirectory(),repository=parent.getChildFile("Samples");
 for(auto f=parent;f!=f.getParentDirectory();f=f.getParentDirectory())if(f.getFileName().equalsIgnoreCase("Presets")){repository=f.getParentDirectory().getChildFile("Samples");break;}
 if(repository.createDirectory().failed())return juce::Result::fail("Could not create the shared Samples folder.");
 juce::String signature=juce::String(audio->rate,10)+":"+juce::String(audio->buffer.getNumSamples())+":"+juce::String(audio->buffer.getNumChannels());
 for(int ch=0;ch<audio->buffer.getNumChannels();++ch)signature+=juce::SHA256(audio->buffer.getReadPointer(ch),(size_t)audio->buffer.getNumSamples()*sizeof(float)).toHexString();
 auto hash=juce::SHA256(signature.toRawUTF8(),signature.getNumBytesAsUTF8()).toHexString();
 auto instrument=repository.getChildFile(destination.getFileNameWithoutExtension());if(instrument.createDirectory().failed())return juce::Result::fail("Could not create the TAL sample folder.");auto stem=juce::File::createLegalFileName(juce::File(audio->librarySourcePath517.isNotEmpty()?audio->librarySourcePath517:audio->path).getFileNameWithoutExtension());if(stem.isEmpty())stem="Sample";auto sample=instrument.getChildFile(stem+".wav");
 if(!sample.existsAsFile()||instrument.getChildFile(".source-sha256").loadFileAsString()!=hash){juce::TemporaryFile temporary(sample);if(!writeRenderedAudio(temporary.getFile(),audio->buffer,audio->rate)||!temporary.overwriteTargetFileWithTemporary())return juce::Result::fail("Could not write the source WAV.");instrument.getChildFile(".source-sha256").replaceWithText(hash);}
 auto xml=juce::parseXML(presetTemplate);if(!xml)return juce::Result::fail("Invalid TAL template.");
 auto* program=xml->getChildByName("programs")->getChildByName("program");program->setAttribute("path",destination.getFullPathName());program->setAttribute("programname",destination.getFileNameWithoutExtension());
 auto* maps=program->getChildByName("samplelayer0")->getChildByName("multisamples");int note=36;
 for(const auto& slice:slices){int begin=juce::jlimit(0,audio->buffer.getNumSamples()-1,slice.start),end=juce::jlimit(begin+1,audio->buffer.getNumSamples(),slice.audibleEnd(audio->rate));auto* m=maps->createNewChildElement("multisample");
 auto relative=sample.getRelativePathFrom(parent);m->setAttribute("url",relative);m->setAttribute("urlRelativeToPresetDirectory",relative);
 for(auto key:{"rootkey","lowkey","highkey"})m->setAttribute(key,note);++note;
 m->setAttribute("startsample",begin);m->setAttribute("endsample",end-1);m->setAttribute("loopstartsample",begin);m->setAttribute("loopendsample",end-1);
 for(auto key:{"loopenabled","isromsample","reverse","phaseinverse","stereoinverse","pingpongloop","mutegroup","attack","release","fadeinsamples","velocitystart","filtermode","filtercutoff","filterresonance","filterkeyfollow","stretchmode","stretchvalue"})m->setAttribute(key,"0");
 for(auto key:{"volume","track","filterhighpass"})m->setAttribute(key,"1");for(auto key:{"detune","transpose","pan","stretchgrainsize"})m->setAttribute(key,"0.5");m->setAttribute("velocityend",127);m->setAttribute("slice",1);
 }
 juce::TemporaryFile temporary(destination);if(!temporary.getFile().replaceWithText(xml->toString())||!temporary.overwriteTargetFileWithTemporary())return juce::Result::fail("Could not save the TAL preset.");if(saved)*saved=destination;return juce::Result::ok();
}
